/* Lot 102: the none keyword in the reader colour and in registered <color> values (generated by scripts/lot102_gen.py; expectations from scripts/lot102_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;
static char g_o[160];

static int syn(const char *s) {
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(s, (int)strlen(s), &g_p);
    return g_p.syntax != 0;
}

/* the reader colour of v as "#rrggbb alpha", "-" when it is not one */
static const char *rc(const char *v) {
    static char b[64];
    unsigned int c = 0xdeadbeefu;
    int a = -7, r = wf_cssprop_color(v, (int)strlen(v), &c, &a);
    if (!r) return c == 0xdeadbeefu && a == -7 ? "-" : "WRITTEN";
    if (r != 1 || c > 0xffffffu || a < 0 || a > 255) return "BAD CODE";
    snprintf(b, sizeof(b), "#%06x %d", c, a);
    return b;
}

static const char *ip(const char *a, const char *b, int t, int code) {
    if (!syn("'<color>'")) return "BAD SYNTAX";
    if (wf_cssprop_interp(&g_p, a, b, t, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

static const char *ad(const char *under, const char *v, int code) {
    if (!syn("'<color>'")) return "BAD SYNTAX";
    if (wf_cssprop_add(&g_p, under, v, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

static int mt(const char *v) {
    if (!syn("'<color>'")) return -1;
    return wf_cssprop_match_prop(&g_p, v) != 0;
}

static void test_l102_none_0(void) {
    TEST_ASSERT_EQUAL_STRING("#000000 255", rc("rgb(none 0 0)"));
    TEST_ASSERT_EQUAL_STRING("#000000 255", rc("rgb(none none none)"));
    TEST_ASSERT_EQUAL_STRING("#000000 0", rc("rgb(0 0 0 / none)"));
    TEST_ASSERT_EQUAL_STRING("#0080ff 128", rc("rgba(none 128 255 / 50%)"));
    TEST_ASSERT_EQUAL_STRING("#ff0000 255", rc("hsl(none 100% 50%)"));
    TEST_ASSERT_EQUAL_STRING("#808080 255", rc("hsl(120 none 50%)"));
    TEST_ASSERT_EQUAL_STRING("#000000 255", rc("hsl(120 100% none)"));
    TEST_ASSERT_EQUAL_STRING("#000000 0", rc("hsla(none none none / none)"));
    TEST_ASSERT_EQUAL_STRING("#ff0000 255", rc("hwb(none 0% 0%)"));
    TEST_ASSERT_EQUAL_STRING("#ff0000 255", rc("hwb(0 none none)"));
    TEST_ASSERT_EQUAL_STRING("#000000 255", rc("lab(none 0 0)"));
    TEST_ASSERT_EQUAL_STRING("#777777 255", rc("lab(50 none none)"));
}

